mthdsContents:
domain      = "candidate_screening"
description = "Analyze a job offer, build a scorecard, score CVs in batch, and generate interview questions or rejection emails."
main_pipe   = "screen_candidates"

[concept.Criterion]
description = "A criterion used to score a CV against a job offer"

[concept.Criterion.structure]
name = { type = "text", description = "Criterion name", required = true }
description = { type = "text", description = "What this criterion evaluates", required = true }
weight = { type = "number", description = "Relative weight of this criterion in the overall score", required = true }
importance = { type = "text", description = "Importance level for this criterion", required = true, choices = [
  "must_have",
  "nice_to_have",
  "differentiator",
] }
evidence_signals = { type = "list", description = "Signals to look for in a CV when scoring this criterion", required = true }

[concept.JobScorecard]
description = "A structured scorecard derived from a job offer"

[concept.JobScorecard.structure]
role_title             = { type = "text", description = "Role title from the job offer", required = true }
role_summary           = { type = "text", description = "Short summary of the role and hiring context", required = true }
threshold              = { type = "number", description = "Minimum score required for a candidate to fit", required = true }
must_have_requirements = { type = "list", description = "Mandatory requirements extracted from the job offer", required = true }
responsibilities       = { type = "list", description = "Main responsibilities of the role", required = true }
criteria               = { type = "list", description = "Weighted scoring criteria for candidate evaluation", required = true }
evaluation_notes       = { type = "text", description = "Guidance for applying the scorecard consistently", required = true }

[concept.CandidateEvaluation]
description = "A scored assessment of one CV against the job scorecard"

[concept.CandidateEvaluation.structure]
candidate_name = { type = "text", description = "Candidate name found in the CV", required = true }
candidate_contact = "Candidate contact details if available"
overall_score = { type = "number", description = "Overall score from 0 to 100", required = true }
decision = { type = "text", description = "Fit decision based on the score threshold", required = true, choices = [
  "fit",
  "reject",
] }
summary = { type = "text", description = "Concise assessment summary", required = true }
strengths = { type = "list", description = "Candidate strengths relevant to the role", required = true }
gaps = { type = "list", description = "Candidate gaps or risks relevant to the role", required = true }
evidence = { type = "list", description = "Evidence from the CV supporting the assessment", required = true }
rationale = { type = "text", description = "Reasoning behind the score and decision", required = true }

[concept.InterviewQuestion]
description = "An interview question generated for a candidate"

[concept.InterviewQuestion.structure]
question  = { type = "text", description = "Question to ask the candidate", required = true }
purpose   = { type = "text", description = "What the question is intended to validate", required = true }
criterion = { type = "text", description = "Scorecard criterion or requirement targeted by the question", required = true }

[concept.CandidateResult]
description = "Final screening output for one candidate"

[concept.CandidateResult.structure]
candidate_name = { type = "text", description = "Candidate name found in the CV", required = true }
candidate_contact = "Candidate contact details if available"
overall_score = { type = "number", description = "Overall score from 0 to 100", required = true }
decision = { type = "text", description = "Final screening decision", required = true, choices = [
  "fit",
  "reject",
] }
summary = { type = "text", description = "Concise assessment summary", required = true }
strengths = { type = "list", description = "Candidate strengths relevant to the role", required = true }
gaps = { type = "list", description = "Candidate gaps or risks relevant to the role", required = true }
rationale = { type = "text", description = "Reasoning behind the score and decision", required = true }
interview_questions = { type = "list", description = "Five interview questions for fit candidates; empty or omitted for rejected candidates" }
rejection_email = "Draft rejection email for rejected candidates; empty or omitted for fit candidates"

[pipe.extract_job_offer]
type        = "PipeExtract"
description = "Extract pages from the job offer document"
inputs      = { job_offer = "Document" }
output      = "Page[]"

[pipe.build_scorecard]
type = "PipeLLM"
description = "Build a scorecard from the job offer"
inputs = { job_offer_pages = "Page[]" }
output = "JobScorecard"
prompt = """
Analyze this job offer and build a hiring scorecard.

Use a fixed threshold of 70 out of 100. Extract the role title, role summary, must-have requirements, responsibilities, and weighted criteria. Criteria weights should be meaningful for the role and should sum to 100. Mark each criterion importance as one of must_have, nice_to_have, or differentiator. Include practical evidence signals that can be checked in CVs.

Job offer pages:
@job_offer_pages
"""

[pipe.extract_cv]
type        = "PipeExtract"
description = "Extract pages from one CV document"
inputs      = { cv = "Document" }
output      = "Page[]"

[pipe.evaluate_candidate]
type = "PipeLLM"
description = "Score one CV against the job scorecard"
inputs = { job_scorecard = "JobScorecard", cv_pages = "Page[]" }
output = "CandidateEvaluation"
prompt = """
Evaluate this CV against the job scorecard.

Rules:
- Score from 0 to 100 using the scorecard criteria and weights.
- Set decision to fit only when overall_score is greater than or equal to the scorecard threshold.
- Set decision to reject when overall_score is below the scorecard threshold.
- Cite concrete evidence from the CV.
- Be strict about must-have requirements and explain important gaps.

Scorecard:
@job_scorecard

CV pages:
@cv_pages
"""

[pipe.prepare_interview_result]
type = "PipeLLM"
description = "Prepare interview questions for a fit candidate"
inputs = { candidate_evaluation = "CandidateEvaluation", job_scorecard = "JobScorecard", cv_pages = "Page[]" }
output = "CandidateResult"
prompt = """
Create the final structured result for a candidate with decision fit.

Use the candidate evaluation fields for name, contact, score, summary, strengths, gaps, and rationale. Generate exactly 5 interview questions. Each question must target a scorecard criterion, must validate a relevant risk or strength, and must be suitable for a first interview. Leave rejection_email empty or omit it.

Candidate evaluation:
@candidate_evaluation

Scorecard:
@job_scorecard

CV pages:
@cv_pages
"""

[pipe.prepare_rejection_result]
type = "PipeLLM"
description = "Prepare a rejection email for a rejected candidate"
inputs = { candidate_evaluation = "CandidateEvaluation", job_scorecard = "JobScorecard", cv_pages = "Page[]" }
output = "CandidateResult"
prompt = """
Create the final structured result for a candidate with decision reject.

Use the candidate evaluation fields for name, contact, score, summary, strengths, gaps, and rationale. Draft a concise, respectful rejection email that thanks the candidate, avoids over-specific negative feedback, and does not mention internal scoring. Leave interview_questions empty or omit them.

Candidate evaluation:
@candidate_evaluation

Scorecard:
@job_scorecard

CV pages:
@cv_pages
"""

[pipe.route_candidate]
type            = "PipeCondition"
description     = "Route candidate by fit decision"
inputs          = { candidate_evaluation = "CandidateEvaluation", job_scorecard = "JobScorecard", cv_pages = "Page[]" }
output          = "CandidateResult"
expression      = "candidate_evaluation.decision"
outcomes        = { fit = "prepare_interview_result", reject = "prepare_rejection_result" }
default_outcome = "prepare_rejection_result"

[pipe.process_cv]
type = "PipeSequence"
description = "Process one CV through scoring and follow-up generation"
inputs = { cv = "Document", job_scorecard = "JobScorecard" }
output = "CandidateResult"
steps = [
  { pipe = "extract_cv", result = "cv_pages" },
  { pipe = "evaluate_candidate", result = "candidate_evaluation" },
  { pipe = "route_candidate", result = "candidate_result" },
]

[pipe.screen_candidates]
type = "PipeSequence"
description = "Screen CVs against a job offer"
inputs = { job_offer = "Document", cvs = "Document[]" }
output = "CandidateResult[]"
steps = [
  { pipe = "extract_job_offer", result = "job_offer_pages" },
  { pipe = "build_scorecard", result = "job_scorecard" },
  { pipe = "process_cv", result = "candidate_results", batch_over = "cvs", batch_as = "cv" },
]
